-- Family (PRIVATE_PERSONAL_RELATIONSHIP): owner-only, never employer accessible. USER project only.
create table if not exists public.family_members (id uuid primary key default gen_random_uuid(), user_id uuid not null, client_ref text, display_name text not null, relationship_type text check (relationship_type in ('parent','sibling','partner','child','grandparent','extended_family','guardian','other')), nickname text, birthday date, timezone text, avatar_url text, contact_frequency_days int, preferred_contact_channel text, linked_communication_thread_id uuid, linked_contact_reference text, notes text, active boolean default true, privacy_classification text default 'PRIVATE_PERSONAL_RELATIONSHIP', created_at timestamptz default now(), updated_at timestamptz default now(), unique(user_id,client_ref));
create table if not exists public.family_dates (id uuid primary key default gen_random_uuid(), user_id uuid not null, family_member_id uuid references public.family_members(id) on delete cascade, client_ref text, type text, title text, date date not null, recurring boolean default false, reminder_days int[] default '{14,7,1}', notes text, created_at timestamptz default now());
create table if not exists public.family_preferences (id uuid primary key default gen_random_uuid(), user_id uuid not null, family_member_id uuid references public.family_members(id) on delete cascade, client_ref text, category text, key text, value text, created_at timestamptz default now());
create table if not exists public.family_interactions (id uuid primary key default gen_random_uuid(), user_id uuid not null, family_member_id uuid references public.family_members(id) on delete cascade, client_ref text, interaction_type text, occurred_at timestamptz not null, source text default 'manual', communication_thread_id uuid, notes text, created_at timestamptz default now());
create table if not exists public.family_gifts (id uuid primary key default gen_random_uuid(), user_id uuid not null, family_member_id uuid references public.family_members(id) on delete cascade, client_ref text, occasion text, gift text, date date, notes text, status text default 'given', created_at timestamptz default now());
create table if not exists public.family_reminder_events (id uuid primary key default gen_random_uuid(), user_id uuid not null, client_ref text, idempotency_key text, family_member_id uuid, type text, title text, due_at timestamptz, notified boolean default false, created_at timestamptz default now(), unique(user_id,idempotency_key));
do $$ declare t text; begin for t in select unnest(array['family_members','family_dates','family_preferences','family_interactions','family_gifts','family_reminder_events']) loop execute format('alter table public.%I enable row level security',t); execute format('drop policy if exists "owner all" on public.%I',t); execute format('create policy "owner all" on public.%I for all using (auth.uid()=user_id) with check (auth.uid()=user_id)',t); end loop; end $$;
